def solve():
    class A:
        def ping(self, out):
            out.append("A")

    class B(A):
        def ping(self, out):
            out.append("B")
            super().ping(out)

    class C(A):
        def ping(self, out):
            out.append("C")
            super().ping(out)

    class D(B, C):
        def ping(self, out):
            out.append("D")
            super().ping(out)

    out = []
    D().ping(out)
    return out
